container.install:
// Who takes part in its jobs is what the modules installed before it declare (`privacy` on the module).
const participants = (job: keyof PrivacyParticipation) =>
  installed
    .filter((m) => m.privacy?.[job])
    .map((m) => m.name)
    .sort()
const privacy = use(
  installPrivacy({
    ...host,
    modules: { identity },
    participants: { exports: participants('exports'), erases: participants('erases') },
  }),
)
